#include BINOMIAL_SOURCE
#include <chrono>
#include <iostream>
#include <string>
#include <tuple>
#include <utility>
using Clock = std::chrono::steady_clock;
struct Scenario { const char* name; std::uint32_t mod, target; int pattern; };
static std::uint64_t rng_state = 543210;
static std::uint64_t random64() { auto x=rng_state; x^=x<<13;x^=x>>7;x^=x<<17;return rng_state=x; }
int main() {
 const Scenario cases[]={
 {"p2_small",2,1,0},{"prime101_small",101,100,0},{"pow2_small",256,255,0},{"oddpow_small",243,242,0},{"crt_small",72,71,0},
 {"prime_large",999983,999982,0},{"pow2_large",524288,524287,0},{"crt_large",720720,720719,0},
 {"prime_lucas",999983,999982,1},{"pow2_random",524288,524287,1},{"crt_random",720720,720719,1},
 {"pow2_nonzero",524288,524287,2},{"crt_nonzero",720720,720719,2},
 {"prime32_fallback",4294967291u,2000,3},{"prime998_fallback",998244353,2000,3}
 };
 std::uint64_t sink=0;
 for(const auto& s:cases) {
  // 同じ法・前計算範囲を使う別の照会分布では、準備時間を重複計測しない。
  if(s.pattern==0 || s.pattern==3) {
   const int rounds=std::clamp<int>(2000000/(s.target+1),3,10000);
   auto start=Clock::now();
   for(int i=0;i<10000;++i) { BinomialMod b(s.mod,0); asm volatile("" : : "g"(&b) : "memory");sink+=b.mod(); }
   auto end=Clock::now();std::cout<<s.name<<",construct0,"<<std::chrono::duration<double,std::nano>(end-start).count()/10000<<','<<sink<<'\n';
   start=Clock::now();
   for(int i=0;i<rounds;++i) { BinomialMod b(s.mod,s.target);asm volatile("" : : "g"(&b) : "memory");sink+=b.COM(s.target,2); }
   end=Clock::now();std::cout<<s.name<<",construct_prepared,"<<std::chrono::duration<double,std::nano>(end-start).count()/rounds<<','<<sink<<'\n';
   double sum=0;
   for(int i=0;i<rounds;++i) { BinomialMod b(s.mod,0);start=Clock::now();b.prepare(s.target);end=Clock::now();sum+=std::chrono::duration<double,std::nano>(end-start).count();sink+=b.COM(s.target,2); }
   std::cout<<s.name<<",prepare,"<<sum/rounds<<','<<sink<<'\n';
  }
  BinomialMod b(s.mod,s.target);std::vector<std::pair<std::int64_t,std::int64_t>> qs;qs.reserve(4096);
  for(int i=0;i<4096;++i) {
   std::uint64_t n,k;
   if(s.pattern==0) { n=random64()%(s.target+1);k=random64()%(n+1); }
   else if(s.pattern==1) { n=random64()%1000000000000000001ULL;k=random64()%(n+1); }
   else if(s.pattern==2) { auto t=random64()%(1000000000000000000ULL/(2*s.mod));n=2*static_cast<std::uint64_t>(s.mod)*(t+1)-1;k=2; }
   else { n=random64()%1000000000000000001ULL;k=2+random64()%7; }
   qs.emplace_back(n,k);
  }
  const int loops=32;auto start=Clock::now();
  for(int j=0;j<loops;++j)for(auto [n,k]:qs) { asm volatile("" : "+g"(n), "+g"(k) : : "memory");sink+=b.COM(n,k); }
  auto end=Clock::now();std::cout<<s.name<<",query,"<<std::chrono::duration<double,std::nano>(end-start).count()/(loops*qs.size())<<','<<sink<<'\n';
 }
}

