// SPDX-License-Identifier: CC0-1.0
#include <array>
#include <charconv>
#include <cstddef>
#include <cstdint>
#include <cstdio>

int main() {
    std::array<char, 1 << 16> input;
    std::size_t position = 0, length = 0;
    const auto get = [&]() -> int {
        if (position == length) {
            length = std::fread(input.data(), 1, input.size(), stdin);
            position = 0;
            if (length == 0) return EOF;
        }
        return static_cast<unsigned char>(input[position++]);
    };
    const auto read = [&]() -> std::uint64_t {
        int c;
        do { c = get(); } while (c != EOF && c <= ' ');
        std::uint64_t value = 0;
        while (c >= '0' && c <= '9') { value = value * 10 + c - '0'; c = get(); }
        return value;
    };
    const auto q = read();
    const auto modulus = static_cast<std::uint32_t>(read());
    BinomialMod comb(modulus, modulus - 1);
    std::array<char, 1 << 16> output;
    char* cursor = output.data();
    for (std::uint64_t i = 0; i < q; ++i) {
        const auto n = static_cast<std::int64_t>(read());
        const auto k = static_cast<std::int64_t>(read());
        if (output.data() + output.size() - cursor < 16) {
            std::fwrite(output.data(), 1, static_cast<std::size_t>(cursor - output.data()), stdout);
            cursor = output.data();
        }
        cursor = std::to_chars(cursor, output.data() + output.size(), comb.COM(n, k)).ptr;
        *cursor++ = '\n';
    }
    std::fwrite(output.data(), 1, static_cast<std::size_t>(cursor - output.data()), stdout);
}

